args.script:
export const meta = {
  name: 'desmon-stage3-eval',
  description: 'Stage 3 (harness v3): Validator/Packer run, then adversarial read-only verifiers per lens, then a completeness critic',
  phases: [
    { title: 'Validate', detail: 'single Validator/Packer agent (mutating: cold gates, spot-check, SPEC sweep, smoke, package, deploy check, exports, handoff)' },
    { title: 'Verify', detail: 'parallel read-only refuters, one lens each, trying to break the validator claims' },
    { title: 'Critique', detail: 'completeness critic over validator output + all verifier findings' },
  ],
}

const S = args.sessionDir
const REPO = args.repo
const BASE = args.base
const SERVER_URL = args.serverUrl
const TODAY = args.today

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    lens: { type: 'string' },
    checks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          command: { type: 'string' },
          result: { type: 'string', enum: ['pass', 'fail', 'skipped'] },
          evidence: { type: 'string' },
        },
        required: ['name', 'command', 'result', 'evidence'],
      },
    },
    discrepancies: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          claim: { type: 'string' },
          reality: { type: 'string' },
          severity: { type: 'string', enum: ['blocking', 'warning', 'info'] },
          fix: { type: 'string' },
        },
        required: ['claim', 'reality', 'severity', 'fix'],
      },
    },
    verdict: { type: 'string', enum: ['SUPPORTS_CONVERGED', 'REFUTES_CONVERGED', 'INCONCLUSIVE'] },
    summary: { type: 'string' },
  },
  required: ['lens', 'checks', 'discrepancies', 'verdict', 'summary'],
}

const CRITIC_SCHEMA = {
  type: 'object',
  properties: {
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          what: { type: 'string' },
          charterStep: { type: 'string' },
          executedNow: { type: 'boolean' },
          command: { type: 'string' },
          result: { type: 'string', enum: ['pass', 'fail', 'not_run'] },
          evidence: { type: 'string' },
          severity: { type: 'string', enum: ['blocking', 'warning', 'info'] },
        },
        required: ['what', 'charterStep', 'executedNow', 'command', 'result', 'evidence', 'severity'],
      },
    },
    handoffEdits: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          section: { type: 'string' },
          problem: { type: 'string' },
          suggestedText: { type: 'string' },
        },
        required: ['section', 'problem', 'suggestedText'],
      },
    },
    overall: { type: 'string', enum: ['CONVERGED', 'NOT_CONVERGED'] },
    reasoning: { type: 'string' },
  },
  required: ['gaps', 'handoffEdits', 'overall', 'reasoning'],
}

phase('Validate')
log('Spawning the Validator/Packer (prompt archived at ' + S + '/prompts/900-validator-packer.md)')
const validatorText = await agent(args.validatorWrapper, { label: 'validator-packer', phase: 'Validate', effort: 'high' })
if (validatorText == null) {
  log('Validator returned null (crashed or skipped) — no verification possible')
  return { verdictLine: null, validatorText: null, verifiers: [], critic: null }
}
const verdictLine = String(validatorText).split('\n')[0]
log('Validator says: ' + verdictLine)

phase('Verify')
const preamble = [
  'You are an independent, ADVERSARIAL verifier in stage 3 of the Desktop Monster harness.',
  'Repo: ' + REPO + ' (branch v3, integration branch of harness v3). Session dir S=' + S + '. Session BASE commit=' + BASE + '. SERVER_URL=' + SERVER_URL + '. Today=' + TODAY + '.',
  'A Validator/Packer agent just finished. Its charter is the file ' + S + '/prompts/900-validator-packer.md (read it to know what it was required to do); its session record is ' + S + '/sessions/stage3-eval.md; its handoff is ' + S + '/handoff.md; its verbatim final message is at the end of this prompt.',
  'Your job: try to REFUTE the validator\'s claims WITHIN YOUR LENS by re-executing the evidence yourself. Never trust a log line you did not reproduce unless reproduction is forbidden below (then mark it skipped and say which validator log file you checked instead). If a claim cannot be reproduced, mark it fail. Be concrete: every check needs the literal command and the literal exit code / output excerpt.',
  'STRICTLY READ-ONLY. Do NOT edit, create, move or delete ANY file in the repo or the session dir. Do NOT run: npm ci, npm install, npm run package, npm run smoke, npm run build, npm start, electron, rm, git commit, git push, git checkout, git merge, git reset, git stash, git worktree, plan.mjs set-status, plan.mjs note, render, graphify update, rgt export commands that write files. ALLOWED: git read-only commands (log, show, diff, status, merge-base, ls-tree, rev-parse), grep/find/cat/ls/wc/awk/sed -n, test -e, node -e (pure), npx vitest run ..., npm test, npm run lint, npm run typecheck, curl, rgt log/blame/sessions to stdout. Other verifiers run vitest concurrently — that is fine. If dist/ exists you may READ it and run node dist/electron/server/index.js on a free port ONLY if your lens says so, and you must kill it.',
  'Return ONLY the structured object (schema enforced). verdict = REFUTES_CONVERGED if any blocking discrepancy or any failing check that the charter maps to NOT CONVERGED; SUPPORTS_CONVERGED if every check in your lens passed or was legitimately skipped; INCONCLUSIVE only if your lens could not be executed at all.',
].join('\n')

const LENSES = [
  {
    key: 'handoff-artifacts',
    prompt: [
      'LENS: handoff structure and artifact existence.',
      '1. ' + S + '/handoff.md exists; first bullets include a status line "- status: COMPLETE" or "- status: INCOMPLETE"; the sections "## Deployment", "## Observability", "## Ponytail audit", "## Test integrity", "## What was built (vs SPEC)", "## How to run", "## Artifacts", "## Gate evidence", "## Manual steps remaining", "## Known limitations", "## Audit trail" ALL exist (grep -n "^## ").',
      '2. "What was built" lists every feature F01..F80 (80 rows; grep -oE "F[0-9]{2}" and compare against SPEC.md feature ids) plus the Server / API rows; each with a pass/fail mark.',
      '3. Every path named in "## Artifacts" and in the validator final message exists (test -e). Specifically release/mac-arm64/DesMon.app and release/DesMon-0.3.0-arm64.dmg must exist AND be newer than the session BASE commit time (stat -f %m vs git show -s --format=%ct ' + BASE + '). A dmg with mtime older than the loop start would mean the validator did not actually package.',
      '4. "## Gate evidence" contains pasted exit lines consistent with ' + S + '/sessions/stage3-*.log files (list them: ls ' + S + '/sessions/stage3*). Cross-check the test count in the gates log (e.g. "Tests  N passed") against the handoff text.',
      '5. "## Observability" names an rgt export and a graph snapshot; check ' + S + '/sessions/stage3.rgt.json, ' + S + '/sessions/stage3.rgt-sessions.txt, ' + S + '/graph/final.GRAPH_REPORT.md exist and are non-empty; count ' + S + '/sessions/iter-*.rgt.json and ' + S + '/graph/iter-*.GRAPH_REPORT.md and compare with the numbers written in the handoff.',
      '6. "## Deployment" quotes a healthz JSON, a sha, an ancestor result, a filter-path result, a postgres expiry; compare against ' + S + '/sessions/stage3-deploy.log and ' + S + '/meta.json (server_url, db_expires) and AGENTS.md (SERVER_URL, DEPLOYED_SHA, DB_EXPIRES).',
      '7. handoff header: iterations used = 23, lanes 3, claude/codex split matches ' + S + '/sessions/dev-loop.md (count rows by worker).',
      '8. git status --porcelain must be empty (the validator was required to commit everything); git log -1 --format=%s must be the chore(eval) commit or later; report the HEAD sha.',
      'Any missing section, missing artifact, stale dmg, or count mismatch is a discrepancy (missing section / missing artifact = blocking; a wrong count = warning).',
    ].join('\n'),
  },
  {
    key: 'spec-sweep-v3',
    prompt: [
      'LENS: literal SPEC sweep of the v3 rows: SPEC.md "### v3 features (F59+)" table (F59..F80) AND every row of "## Server / API" AND the git-side half of "## Deployment".',
      'For EACH row, extract the AC cell (last column) and execute it literally from the repo root. Most ACs are vitest test names: run npx vitest run <file> -t "<exact test title>" and require "1 passed" (or the listed count) with zero failures AND zero "no tests found" — a vitest run that matches 0 tests is a FAIL, not a pass. grep/test -e/node -e ACs run as written.',
      'FORBIDDEN in your lens: any AC that requires npm ci / npm run package / npm run smoke / npm run build / a live push / render CLI — mark it skipped, state the reason, and instead quote the validator\'s corresponding line from ' + S + '/sessions/stage3-eval.md or ' + S + '/sessions/stage3-spec-sweep.log (if present). For the Deployment section\'s healthz curl you MAY run curl -fsS --max-time 90 ' + SERVER_URL + '/healthz once.',
      'Report one check per row (name = F-id or endpoint), with command and exit code. Also report the total: rows executed / passed / failed / skipped. Any executed failure = blocking discrepancy naming the row.',
    ].join('\n'),
  },
  {
    key: 'spec-sweep-v1',
    prompt: [
      'LENS: literal SPEC sweep of the v1 feature table in SPEC.md "## Features" (rows F01..F27, the first table before "### v2 features").',
      'For EACH row, extract the AC cell (last column) and execute it literally from the repo root. Vitest ACs: npx vitest run <file> -t "<exact test title>" must report the expected passes with zero failures AND must not match 0 tests (0 matched = FAIL). grep/test -e/node -e ACs run as written.',
      'FORBIDDEN in your lens: npm ci / npm run package / npm run smoke / npm run build / npm start / electron / network. For an AC that needs them (e.g. F01 is npm ci && ...; smoke/package rows), run only the read-only part (e.g. npm test && npm run lint && npm run typecheck for F01) and mark the rest skipped, quoting the validator\'s corresponding evidence line from ' + S + '/sessions/stage3-eval.md or ' + S + '/sessions/stage3-*.log.',
      'Report one check per row (name = F-id), command, exit code; totals executed / passed / failed / skipped. Any executed failure = blocking discrepancy naming the row.',
    ].join('\n'),
  },
  {
    key: 'spec-sweep-v2',
    prompt: [
      'LENS: literal SPEC sweep of the v2 feature table in SPEC.md "### v2 features (F28+)" (rows F28..F58).',
      'For EACH row, extract the AC cell (last column) and execute it literally from the repo root. Vitest ACs: npx vitest run <file> -t "<exact test title>" must report the expected passes with zero failures AND must not match 0 tests (0 matched = FAIL). grep/test -e/node -e ACs run as written.',
      'FORBIDDEN in your lens: npm ci / npm run package / npm run smoke / npm run build / npm start / electron / render CLI / git push. For an AC that needs them, mark skipped with the reason and quote the validator\'s evidence line from ' + S + '/sessions/stage3-eval.md or ' + S + '/sessions/stage3-*.log. A healthz curl (curl -fsS --max-time 90 ' + SERVER_URL + '/healthz) is allowed once if a row needs it.',
      'Report one check per row (name = F-id), command, exit code; totals executed / passed / failed / skipped. Any executed failure = blocking discrepancy naming the row.',
    ].join('\n'),
  },
  {
    key: 'plan-spotcheck',
    prompt: [
      'LENS: plan-task AC spot-check for the v3 tasks T54..T76 in IMPLEMENTATION_PLAN.md (headings "### [x] T54" .. "### [x] T76"; read only those blocks, e.g. sed -n "/^### \\[x\\] T54/,/^### \\[x\\] T77/p" or awk between the headings).',
      'The charter required the validator to execute the AC: of (a) 3 random [x] tasks from T54+, (b) every task whose title mentions window/input/package/smoke/server/deploy/party/battle/theft/field, (c) every NOTHING_TO_DO task (T75). Enumerate the mandatory set yourself and compare with the set the validator lists in ' + S + '/sessions/stage3-eval.md and/or ' + S + '/sessions/stage3-spotcheck.log — a mandatory task the validator did not execute is a blocking discrepancy.',
      'Then execute EVERY T54..T76 AC line yourself (all 23, not a sample), literally from the repo root, with DESMON_SKIP_NET=1 exported for deploy tasks (T73, T74). Vitest ACs must not match 0 tests. FORBIDDEN: npm ci / npm run package / npm run smoke / npm run build / npm start / electron / git push / render CLI — for an AC containing those (T75 packaging, any smoke), run the read-only part, verify the produced artifact exists instead (test -e release/DesMon-0.3.0-arm64.dmg, test -d release/mac-arm64/DesMon.app), mark the mutating part skipped and quote the validator evidence line. Also verify T75\'s "no pg and no server build inside the .app" claim read-only: find release/mac-arm64/DesMon.app -path "*node_modules/pg*" and check for dist/electron/server inside the app resources (asar: npx asar list if available, else grep -c on app.asar) — follow whatever the T75 AC literally says.',
      'Report one check per task (name = T-id), command, exit code; totals. Any executed failure = blocking discrepancy naming the task and the exact command (the orchestrator will flip the task via plan.mjs — you do not).',
    ].join('\n'),
  },
  {
    key: 'deploy-rule',
    prompt: [
      'LENS: deployment verification (charter step 7 and step 12) done independently.',
      '1. SERVER_URL=$(sed -n "s/^SERVER_URL=//p" AGENTS.md) must equal ' + SERVER_URL + ' and ' + S + '/meta.json server_url. Placeholder / empty = blocking.',
      '2. curl -fsS --retry 5 --retry-delay 30 --max-time 90 "$SERVER_URL/healthz" yourself → JSON {"ok":true,"sha":"<sha>"}; report verbatim. Compare with ' + S + '/sessions/stage3-deploy.log (must exist, non-empty, same sha unless the validator redeployed — if so it must say so in handoff §Deployment).',
      '3. Deploy rule, no equality against any particular commit: git merge-base --is-ancestor <sha> HEAD (exit 0 required) AND git log <sha>..HEAD -- src/server src/core src/shared package.json package-lock.json tsconfig.main.json .node-version prints NOTHING. Report both verbatim. Also report git log --oneline <sha>..HEAD (all commits after the deployed sha) so the orchestrator can see what is un-deployed (docs/agentdoc commits are fine).',
      '4. Cross-check AGENTS.md DEPLOYED_SHA, RENDER_SERVICE_ID, RENDER_POSTGRES_ID, DB_EXPIRES against handoff §Deployment text (service id, expiry date). db_expires in ' + S + '/meta.json is 2026-10-03; today is ' + TODAY + ' — compute days remaining; if within 7 days or past, the handoff §Deployment and §Manual steps must carry a WARNING line (otherwise no warning is expected — flag a spurious warning as info).',
      '5. Local hermetic boot (allowed for THIS lens only, read-only otherwise): if dist/electron/server/index.js exists, PORT=<free port> node dist/electron/server/index.js & (no DATABASE_URL), curl -fsS http://127.0.0.1:<port>/healthz → {"ok":true,"sha":"dev"}, then kill it. If dist/ is missing, skip and say so (do NOT build).',
      '6. Optional probe (network, read-only for the server semantics): if dist/electron/server/probe.js exists, node dist/electron/server/probe.js "$SERVER_URL" once and report the exit code and last line (it registers a throwaway player; that is the documented verification path in AGENTS.md §Server).',
      'Stale deploy (rule fails) or unreachable healthz = blocking ("deploy not landed").',
    ].join('\n'),
  },
  {
    key: 'integrity-deps-workers',
    prompt: [
      'LENS: test integrity, dependency check, codex worker-rule, ponytail format — charter steps 9, 10, 11 redone independently, then compared with handoff §Test integrity / §Ponytail audit / §Observability.',
      '1. Test integrity: for every tests/**/*.test.ts present at BASE (git ls-tree -r --name-only ' + BASE + ' -- tests | grep "\\.test\\.ts$"), compare git show ' + BASE + ':<f> | grep -cE "^\\s*(it|test)\\(" with the same at HEAD (missing at HEAD = 0). List every file with base→head counts. ANY decrease = blocking (and run rgt blame tests/<f> to name the step/agent). Compare your result with handoff §Test integrity (it must say "none" if no decrease).',
      '2. Dependencies: git diff ' + BASE + '..HEAD -- package.json | grep -E "^\\+\\s+\\"[^\\"]+\\": \\"" — list additions; each dependency addition must be pg or be named with a ladder rung in some task Notes (grep -n "<dep>" IMPLEMENTATION_PLAN.md). "version": "0.3.0" is a version bump, not a dependency. grep -c "@types/pg" package.json must be 0. Compare with handoff §Ponytail audit dependency line.',
      '3. Worker rule: git log --format="%H %s" ' + BASE + '..HEAD | grep "\\[codex\\]" → for each commit git show --stat --format= <sha> -- . ":!IMPLEMENTATION_PLAN.md" ":!.agentdoc" must list only graphics-set paths (src/renderer/sprites/**, src/renderer/anim.ts, src/renderer/hud.ts, src/renderer/effects.ts, static/style.css, static/menu.css, tests/sprites.test.ts, tests/anim.test.ts, tests/effects.test.ts, tests/renderer.test.ts, tests/window.test.ts). List every path per commit. A non-graphics path = warning; package.json/package-lock.json touched = blocking. Compare with handoff §Observability worker-rule line.',
      '4. Ponytail: handoff §Ponytail audit must contain (a) review lines in .harness/v3/reference/PONYTAIL.md §2 one-line format ending with "net: -N lines possible." or "Lean already. Ship."; (b) audit lines in §3 format ending with "net: -N lines, -M deps possible." or "Lean already. Ship."; (c) the dependency line. Read PONYTAIL.md §2/§3 to know the format and check the handoff literally follows it (format violation = warning). Spot-check 3 of the review findings against git diff ' + BASE + '..HEAD -- src tests: does the cited file:line exist and say what the finding claims? A fabricated citation = warning.',
      '5. Loop drained evidence: git worktree list shows only the main checkout; ls ' + S + '/lanes/ is empty of .pid without .rc; node .harness/v3/loop/plan.mjs open prints nothing; grep -c "^### \\[ \\]\\|^### \\[~\\]\\|^### \\[!\\]" IMPLEMENTATION_PLAN.md is 0 (if the validator flipped tasks back, this is where you see it — report which).',
    ].join('\n'),
  },
]

const verifiers = (await parallel(LENSES.map(l => () =>
  agent(preamble + '\n\n## Your lens\n' + l.prompt + '\n\n## Validator final message (verbatim)\n' + validatorText,
    { label: 'verify:' + l.key, phase: 'Verify', schema: VERIFY_SCHEMA })
    .then(r => (r ? { key: l.key, ...r } : null))
))).filter(Boolean)
const dropped = LENSES.length - verifiers.length
if (dropped) log('WARNING: ' + dropped + ' verifier(s) returned null (crashed/skipped) — coverage incomplete')
for (const v of verifiers) {
  const fails = v.checks.filter(c => c.result === 'fail').length
  const blocking = v.discrepancies.filter(d => d.severity === 'blocking').length
  log('verify:' + v.key + ' → ' + v.verdict + ' (' + v.checks.length + ' checks, ' + fails + ' fail, ' + blocking + ' blocking)')
}

phase('Critique')
const criticPrompt = [
  'You are the completeness critic of stage 3 of the Desktop Monster harness. Repo ' + REPO + ', branch v3, session dir ' + S + ', BASE ' + BASE + ', SERVER_URL ' + SERVER_URL + ', today ' + TODAY + '.',
  'Inputs: (1) the validator charter at ' + S + '/prompts/900-validator-packer.md (protocol steps 0–12 + handoff duties), (2) the validator\'s final message (below), (3) the structured findings of ' + verifiers.length + ' read-only verifiers (below), (4) the files on disk: ' + S + '/handoff.md, ' + S + '/sessions/stage3-eval.md, ' + S + '/sessions/stage3*.log.',
  'Task: ask "what is MISSING?" — a charter step nobody executed or evidenced, a handoff-template field left as a placeholder (<...> or TODO) or empty, a claim in the validator message that no verifier reproduced, a verifier check marked skipped whose validator evidence line does not actually exist in the logs, a contradiction between two verifiers. For each gap: if it is READ-ONLY and cheap (grep, test -e, git read commands, npx vitest run -t, curl healthz once), EXECUTE IT NOW and report the result with the literal command; otherwise mark result not_run and say why.',
  'STRICTLY READ-ONLY (same rules as the verifiers: no npm ci/package/smoke/build, no rm, no git write commands, no plan.mjs writes, no file edits).',
  'Also produce handoffEdits: concrete text corrections the orchestrator should apply to ' + S + '/handoff.md (wrong numbers, missing WARNING lines, placeholders, sections that do not follow .harness/v3/templates/handoff.template.md). Quote the exact section heading.',
  'overall = NOT_CONVERGED if any blocking gap or any verifier REFUTES_CONVERGED with a blocking discrepancy that you could not show to be a verifier error; otherwise CONVERGED. Explain in reasoning, citing check names.',
  '',
  '## Validator final message (verbatim)',
  String(validatorText),
  '',
  '## Verifier findings (JSON)',
  JSON.stringify(verifiers, null, 1),
].join('\n')
const critic = await agent(criticPrompt, { label: 'completeness-critic', phase: 'Critique', schema: CRITIC_SCHEMA, effort: 'high' })
log('Critic overall: ' + (critic ? critic.overall : 'null'))

return { verdictLine, validatorText, verifiers, dropped, critic }

